package glitch

import data.glitch_lib

download_attr_names := {"url", "source", "src", "uri"}

integrity_attr_names := {"checksum", "sha256", "sha512", "sha1", "md5", "hash", "integrity", "digest"}

is_remote_url(value) {
    value.ir_type == "String"
    regex.match("(?i)^(https?|ftp)://", value.value)
}

has_download_attr(node) {
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    lower(attr.name) == download_attr_names[_]
    is_remote_url(attr.value)
}

has_integrity_attr(node) {
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    lower(attr.name) == integrity_attr_names[_]
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    has_download_attr(node)
    not has_integrity_attr(node)

    result := {
        "type": "sec_no_int_check",
        "element": node,
        "path": parent.path,
        "description": "Missing support for integrity check - Resources downloaded from remote URLs without checksum/hash verification are susceptible to data corruption or tampering. (CWE-353)"
    }
}

package glitch

